def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def runs(values, color):
        out, start = [], None
        for i in range(len(values) + 1):
            v = values[i] if i < len(values) else None
            if v == color and start is None:
                start = i
            elif v != color and start is not None:
                out.append((start, i - 1))
                start = None
        return out

    def paired(a, b):
        result = []
        for color in set(a) & set(b):
            if color == bg:
                continue
            for x in runs(a, color):
                for y in runs(b, color):
                    if x[1] - x[0] == y[1] - y[0]:
                        result.append((color, x, y))
        return result

    vertical = paired([g[r][0] for r in range(h)], [g[r][w-1] for r in range(h)])
    horizontal = paired([g[0][c] for c in range(w)], [g[h-1][c] for c in range(w)])
    v_length = max((x[1] - x[0] + 1 for _, x, _ in vertical), default=0)
    h_length = max((x[1] - x[0] + 1 for _, x, _ in horizontal), default=0)
    if vertical and v_length >= h_length:
        bar, left, right = vertical[0]
        marks = [(r, c, g[r][c]) for r in range(h) for c in range(1, w-1)
                 if g[r][c] != bg and g[r][c] != bar]
        for r, c, color in marks:
            if left[0] <= r <= left[1]:
                rr = right[0] + r - left[0]
                # Draw the source ray out toward its own edge, and a full counterpart ray.
                for cc in range(1, c):
                    if g[r][cc] == bg:
                        g[r][cc] = color
                for cc in range(1, w-1):
                    if g[rr][cc] == bg:
                        g[rr][cc] = color
                g[r][c] = 4
            elif right[0] <= r <= right[1]:
                rr = left[0] + r - right[0]
                for cc in range(c+1, w-1):
                    if g[r][cc] == bg:
                        g[r][cc] = color
                for cc in range(1, w-1):
                    if g[rr][cc] == bg:
                        g[rr][cc] = color
                g[r][c] = 4
        return g

    if horizontal:
        bar, top, bottom = horizontal[0]
        marks = [(r, c, g[r][c]) for r in range(1, h-1) for c in range(w)
                 if g[r][c] != bg and g[r][c] != bar]
        originals = []
        for r, c, color in marks:
            if top[0] <= c <= top[1]:
                cc = bottom[0] + c - top[0]
                dr = -1
                counterpart_edge = h - 1
            elif bottom[0] <= c <= bottom[1]:
                cc = top[0] + c - bottom[0]
                dr = 1
                counterpart_edge = 0
            else:
                continue
            originals.append((r, c))
            # Project the source toward its associated bar; the translated copy
            # starts at the opposite bar and continues across the interior.
            rr = r + dr
            while 0 <= rr < h:
                if g[rr][c] == bg:
                    g[rr][c] = color
                rr += dr
            rr = 1 if counterpart_edge == 0 else h - 2
            step = 1 if counterpart_edge == 0 else -1
            while 0 <= rr < h - 1:
                if g[rr][cc] == bg:
                    g[rr][cc] = color
                rr += step
        for r, c in originals:
            g[r][c] = 4
    return g

